  private config: IConfigService;
  private logger: QELogger;
  private activeHandles: Map<string, AgentHandleImpl | TaskHandleImpl> = new Map();

  constructor(
    agents: IAgentService,
    tasks: ITaskService,
    workflows: IWorkflowService,
    config: IConfigService,
    logger: QELogger
  ) {
    this.agents = agents;
    this.tasks = tasks;
    this.workflows = workflows;
    this.config = config;
    this.logger = logger;
  }

  /**
   * Spawn a test execution agent via V3 Core
   */
  async spawnTestExecutor(
    testSuite: TestSuite,
    config: ExecutorConfig
  ): Promise<AgentHandle> {
    try {
      this.logger.info(`Spawning test executor for suite: ${testSuite.name}`);

      const agentConfig = QE_AGENT_CONFIGS['qe-test-executor'];

      const spawnedAgent = await this.agents.spawn({
        type: 'qe-test-executor',
        name: `test-executor-${testSuite.id}`,
        capabilities: [
          ...agentConfig.capabilities!,
          testSuite.framework, // Add framework-specific capability
        ],
        config: {
          testSuiteId: testSuite.id,
          parallel: config.parallel,
          maxWorkers: config.maxWorkers,
          retryCount: config.retryCount,
          timeout: config.timeout,
          testCount: testSuite.testCases.length,
          estimatedDuration: testSuite.estimatedDuration,
        },
        model: agentConfig.model,
      });

      const handle = new AgentHandleImpl(
        spawnedAgent,
        this.agents,
        this.logger
      );

      this.activeHandles.set(handle.id, handle);
      this.logger.debug(`Spawned test executor: ${handle.id}`);

      return handle;
    } catch (error) {
      this.logger.error('Failed to spawn test executor', error);
      throw new QECoreError('Failed to spawn test executor', error as Error);
    }
  }

  /**
   * Create a test execution task via V3 Task Service
   */
  async createTestTask(
    testSuite: TestSuite,
    priority: Priority
  ): Promise<TaskHandle> {
    try {
      this.logger.info(`Creating test task for suite: ${testSuite.name} (priority: ${priority})`);

      const createdTask = await this.tasks.create({
        type: 'test-execution',
        description: `Execute test suite: ${testSuite.name}`,
        priority,
        payload: {
          testSuiteId: testSuite.id,
          testCount: testSuite.testCases.length,
          framework: testSuite.framework,
          config: testSuite.config,
        },
        timeout: testSuite.estimatedDuration * 2, // 2x safety margin
      });

      const handle = new TaskHandleImpl(
        createdTask,
        this.tasks,
        this.logger
      );

      this.activeHandles.set(handle.id, handle);
      this.logger.debug(`Created test task: ${handle.id}`);

      return handle;
    } catch (error) {
      this.logger.error('Failed to create test task', error);
      throw new QECoreError('Failed to create test task', error as Error);
    }
  }

  /**
   * Execute quality gate workflow
   */
  async executeQualityGateWorkflow(
    gates: QualityGate[],
    metrics: QualityMetrics
  ): Promise<WorkflowResult> {
    try {
      this.logger.info(`Executing quality gate workflow with ${gates.length} gates`);

      // Build workflow steps from quality gates
      const steps: WorkflowStep[] = gates.map((gate) => ({
        name: `gate-${gate.id}`,
        type: 'condition' as const,
        config: {
          gateId: gate.id,
          gateName: gate.name,
          criteria: gate.criteria,
          metrics,
          required: gate.required,
          weight: gate.weight,
        },
      }));

      const result = await this.workflows.execute({
        name: 'quality-gate-evaluation',
        steps,
        failFast: true, // Stop on first required gate failure
        timeout: 30000, // 30s timeout
      });

      // Transform to QE format
      const workflowResult: WorkflowResult = {
        workflowId: result.workflowId,
        success: result.success,
        stepResults: result.stepResults.map((step) => this.transformStepResult(step, gates)),
        durationMs: result.durationMs,
        output: this.buildQualityGateOutput(result.stepResults, gates, metrics),
      };

      this.logger.info(`Quality gate workflow complete: ${result.success ? 'PASSED' : 'FAILED'}`);
      return workflowResult;
    } catch (error) {
      this.logger.error('Quality gate workflow failed', error);
      throw new QECoreError('Quality gate workflow failed', error as Error);
    }
  }

  /**
   * Get configuration value
   */
  async getConfig<T>(key: string): Promise<T | undefined> {
    try {
      return await this.config.get<T>(key);
    } catch (error) {
      this.logger.warn(`Failed to get config: ${key}`, error);
      return undefined;
    }
  }

  /**
   * List available agents by type
   */
  async listAgents(filter?: { type?: string; status?: string }): Promise<AgentHandle[]> {
    try {
      this.logger.debug(`Listing agents with filter: ${JSON.stringify(filter)}`);

      const agents = await this.agents.list({
        type: filter?.type,
        status: filter?.status,
      });

      // Filter to only QE agents
      const qeAgents = agents.filter((a) => a.type.startsWith('qe-'));

      return qeAgents.map((agent) => new AgentHandleImpl(agent, this.agents, this.logger));
    } catch (error) {
      this.logger.error('Failed to list agents', error);
      throw new QECoreError('Failed to list agents', error as Error);
    }
  }

  /**
   * Get agent by ID
   */
  async getAgent(agentId: string): Promise<AgentHandle | null> {
    try {
      // Check active handles first
      const activeHandle = this.activeHandles.get(agentId);
      if (activeHandle && 'type' in activeHandle) {
        return activeHandle as AgentHandle;
      }

      const agent = await this.agents.get(agentId);
      if (!agent) return null;

      return new AgentHandleImpl(agent, this.agents, this.logger);
    } catch (error) {
      this.logger.error(`Failed to get agent: ${agentId}`, error);
      return null;
    }
  }

  /**
   * Transform workflow step result to QE format
   */
  private transformStepResult(
    step: WorkflowExecutionResult['stepResults'][0],
    gates: QualityGate[]
  ): StepResult {
    const gateId = step.name.replace('gate-', '');
    const gate = gates.find((g) => g.id === gateId);

    return {
      name: gate?.name || step.name,
      passed: step.passed,
      output: step.output,
      error: step.error,
      durationMs: step.durationMs,
    };
  }

  /**
   * Build quality gate output summary
   */
  private buildQualityGateOutput(
    stepResults: WorkflowExecutionResult['stepResults'],
    gates: QualityGate[],
    metrics: QualityMetrics
  ): Record<string, unknown> {
    const passedGates = stepResults.filter((s) => s.passed).length;
    const failedGates = stepResults.filter((s) => !s.passed).length;
    const requiredFailed = stepResults.filter((s, i) => !s.passed && gates[i]?.required).length;

    // Calculate weighted score
    let totalWeight = 0;
    let achievedWeight = 0;
    stepResults.forEach((step, i) => {
      const gate = gates[i];
      if (gate) {
        totalWeight += gate.weight;
        if (step.passed) achievedWeight += gate.weight;
      }
    });

    const overallScore = totalWeight > 0 ? (achievedWeight / totalWeight) * 100 : 0;

    return {
      summary: {
        passedGates,
        failedGates,
        requiredFailed,
        overallScore: Math.round(overallScore * 10) / 10,
        releaseReady: requiredFailed === 0,
      },
      metrics,
      gateDetails: stepResults.map((step, i) => ({
        id: gates[i]?.id,
        name: gates[i]?.name,
        passed: step.passed,
        required: gates[i]?.required,
        weight: gates[i]?.weight,
        error: step.error,
      })),
    };
  }
}

/**
 * Agent Handle Implementation
 */
class AgentHandleImpl implements AgentHandle {
  readonly id: string;
  readonly type: string;
  readonly name: string;
  private _status: AgentHandle['status'];
  private agentService: IAgentService;
  private logger: QELogger;

  constructor(
    agent: SpawnedAgent,
    agentService: IAgentService,
    logger: QELogger
  ) {
    this.id = agent.id;
    this.type = agent.type;
    this.name = agent.name;
    this._status = agent.status;
    this.agentService = agentService;
    this.logger = logger;
  }

  get status(): AgentHandle['status'] {
    return this._status;
  }

  async terminate(): Promise<void> {
    try {
      this.logger.debug(`Terminating agent: ${this.id}`);
      await this.agentService.terminate(this.id);
      this._status = 'terminated';
    } catch (error) {
      this.logger.error(`Failed to terminate agent: ${this.id}`, error);
      throw new QECoreError('Failed to terminate agent', error as Error);
    }
  }

  async send(message: Record<string, unknown>): Promise<void> {
    try {
      this.logger.debug(`Sending message to agent: ${this.id}`);
      await this.agentService.sendMessage(this.id, message);
    } catch (error) {
      this.logger.error(`Failed to send message to agent: ${this.id}`, error);
      throw new QECoreError('Failed to send message', error as Error);
    }
  }
}

/**
 * Task Handle Implementation
 */
class TaskHandleImpl implements TaskHandle {
  readonly id: string;
  readonly type: string;
  private _status: TaskHandle['status'];
  private taskService: ITaskService;
  private logger: QELogger;

  constructor(
    task: CreatedTask,
    taskService: ITaskService,
    logger: QELogger
  ) {
    this.id = task.id;
    this.type = task.type;
    this._status = task.status;
    this.taskService = taskService;
    this.logger = logger;
  }

  get status(): TaskHandle['status'] {
    return this._status;
  }

  async wait(): Promise<TaskResult> {
    try {
      this.logger.debug(`Waiting for task completion: ${this.id}`);
      const result = await this.taskService.waitForCompletion(this.id);

      this._status = result.success ? 'completed' : 'failed';

      return {
        taskId: this.id,
        success: result.success,
        data: result.data,
        error: result.error,
        durationMs: result.durationMs,
      };
    } catch (error) {
      this.logger.error(`Failed to wait for task: ${this.id}`, error);
      throw new QECoreError('Failed to wait for task', error as Error);
    }
  }

  async cancel(): Promise<void> {
    try {
      this.logger.debug(`Cancelling task: ${this.id}`);
      await this.taskService.cancel(this.id);
      this._status = 'cancelled';
    } catch (error) {
      this.logger.error(`Failed to cancel task: ${this.id}`, error);
      throw new QECoreError('Failed to cancel task', error as Error);
    }
  }

  async getProgress(): Promise<TaskProgress> {
    try {
      const status = await this.taskService.getStatus(this.id);
      this._status = status.status;

      return {
        percentage: status.progress || 0,
        currentStep: status.currentStep || 'Unknown',
        totalSteps: status.totalSteps || 0,
        completedSteps: status.completedSteps || 0,
        estimatedRemainingMs: this.estimateRemaining(status),
      };
    } catch (error) {
      this.logger.error(`Failed to get task progress: ${this.id}`, error);
      throw new QECoreError('Failed to get progress', error as Error);
    }
  }

  private estimateRemaining(status: TaskStatus): number {
    if (!status.totalSteps || !status.completedSteps) return 0;
    if (status.completedSteps >= status.totalSteps) return 0;

    // Rough estimate: 1 second per remaining step
    const remainingSteps = status.totalSteps - status.completedSteps;
    return remainingSteps * 1000;
  }
}

/**
 * QE Core Error class
 */
export class QECoreError extends Error {
  public readonly cause?: Error;

  constructor(message: string, cause?: Error) {
    super(message);
    this.name = 'QECoreError';
    this.cause = cause;
  }
}

/**
 * QE Hive Bridge
 *
 * Anti-corruption layer for V3 Hive-Mind coordination integration.
 * Handles Queen coordinator registration, worker spawning, consensus,
 * and Byzantine fault-tolerant task execution.
 *
 * Integrates with V3 Hive-Mind services:
 * - Queen role registration for QE coordination
 * - Worker capability announcement
 * - Consensus for agent allocation
 * - Shared memory for coordination state
 *
 * Based on:
 * - ADR-030: Agentic-QE Plugin Integration
 * - ADR-007: Hive-Mind Consensus
 *
 * @module v3/plugins/agentic-qe/bridges/QEHiveBridge
 */

import type {
  IQEHiveBridge,
  HiveRole,
  QESwarmTask,
  QESwarmResult,
  AgentTaskResult,
  ConsensusResult,
  QELogger,
} from '../interfaces.js';

// V3 Hive-Mind types (would be imported from @claude-flow/coordination in production)
interface IHiveMindService {
  join(config: HiveJoinConfig): Promise<void>;
  leave(agentId: string): Promise<void>;
  consensus(proposal: ConsensusProposal): Promise<HiveConsensusResult>;
  broadcast(message: HiveBroadcastMessage): Promise<void>;
  memory(operation: HiveMemoryOperation): Promise<HiveMemoryResult>;
  getStatus(): Promise<HiveStatus>;
  getWorkers(): Promise<HiveWorker[]>;
}

interface HiveJoinConfig {
  agentId: string;
  role: HiveRole;
  capabilities: string[];
  metadata?: Record<string, unknown>;
}

interface ConsensusProposal {
  action: 'propose' | 'vote' | 'status';
  type?: string;
  value?: Record<string, unknown>;
  proposalId?: string;
  vote?: boolean;
}

interface HiveConsensusResult {
  accepted: boolean;
  reason?: string;
  votesFor: number;
  votesAgainst: number;
  totalVoters: number;
  proposalId?: string;
}

interface HiveBroadcastMessage {
  message: string;
  priority: 'low' | 'normal' | 'high' | 'critical';
  fromId: string;
  targetRole?: string;
}

interface HiveMemoryOperation {
  action: 'get' | 'set' | 'delete' | 'list';
  key?: string;
  value?: string;
}

interface HiveMemoryResult {
  success: boolean;
  value?: string;
  keys?: string[];
}

interface HiveStatus {
  initialized: boolean;
  topology: string;
  queenId: string | null;
  workerCount: number;
  consensusAlgorithm: string;
}

interface HiveWorker {
  id: string;
  role: HiveRole;
  capabilities: string[];
  status: 'active' | 'idle' | 'busy';
  lastHeartbeat: number;
}

/**
 * QE-specific capabilities for hive workers
 */
const QE_CAPABILITIES = {
  testGeneration: [
    'unit-test-generation',
    'integration-test-generation',
    'e2e-test-generation',
    'property-test-generation',
  ],
  testExecution: [
    'test-execution',
    'parallel-execution',
    'result-aggregation',
  ],
  coverageAnalysis: [
    'coverage-collection',
    'gap-detection',
    'priority-ranking',
  ],
  qualityAssessment: [
    'quality-gate-evaluation',
    'risk-assessment',
    'readiness-assessment',
  ],
  securityCompliance: [
    'sast-scanning',
    'dast-scanning',
    'compliance-checking',
  ],
} as const;

/**
 * QE Hive Bridge Implementation
 *
 * Bridges agentic-qe coordination needs to V3's Hive-Mind.
 * Manages Queen registration, worker spawning, and BFT execution.
 */
export class QEHiveBridge implements IQEHiveBridge {
  private hiveMind: IHiveMindService;
  private logger: QELogger;
  private queenId: string;
  private spawnedWorkers: Map<string, string> = new Map(); // workerId -> agentType
  private initialized: boolean = false;

  constructor(
    hiveMind: IHiveMindService,
    logger: QELogger
  ) {
    this.hiveMind = hiveMind;
    this.logger = logger;
    this.queenId = `aqe-queen-${Date.now()}`;
  }

  /**
   * Get the Queen identifier
   */
  getQueenId(): string {
    return this.queenId;
  }

  /**
   * Register QE Queen with Hive Mind
   */
  async registerQueen(): Promise<void> {
    if (this.initialized) {
      this.logger.debug('QE Queen already registered');
      return;
    }

    try {
      this.logger.info(`Registering QE Queen: ${this.queenId}`);

      await this.hiveMind.join({
        agentId: this.queenId,
        role: 'queen',
        capabilities: [
          'qe-coordination',
          'test-orchestration',
          'coverage-coordination',
          'quality-gate-enforcement',
          'security-scan-coordination',
        ],
        metadata: {
          source: 'agentic-qe',
          version: '3.2.3',
          contexts: [
            'test-generation',
            'test-execution',
            'coverage-analysis',
            'quality-assessment',
            'defect-intelligence',
            'security-compliance',
          ],
        },
      });

      this.initialized = true;
      this.logger.info('QE Queen registered successfully');
    } catch (error) {
      this.logger.error('Failed to register QE Queen', error);
      throw new QEHiveError('Failed to register Queen', error as Error);
    }
  }

  /**
   * Spawn a QE worker and join to hive
   */
  async spawnQEWorker(agentType: string, context: string): Promise<string> {
    this.ensureInitialized();

    try {
      const workerId = `aqe-${agentType}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      this.logger.info(`Spawning QE worker: ${workerId} (type: ${agentType}, context: ${context})`);

      // Get capabilities for this agent type
      const capabilities = this.getCapabilitiesForAgent(agentType, context);

      await this.hiveMind.join({
        agentId: workerId,
        role: 'worker',
        capabilities,
        metadata: {
          parentQueen: this.queenId,
          agentType,
          qeContext: context,
          spawnedAt: Date.now(),
        },
      });

      this.spawnedWorkers.set(workerId, agentType);
      this.logger.debug(`QE worker spawned: ${workerId}`);

      return workerId;
    } catch (error) {
      this.logger.error(`Failed to spawn QE worker: ${agentType}`, error);
      throw new QEHiveError('Failed to spawn worker', error as Error);
    }
  }

  /**
   * Coordinate a QE swarm task
   */
  async coordinateQESwarm(task: QESwarmTask): Promise<QESwarmResult> {
    this.ensureInitialized();

    try {
      this.logger.info(`Coordinating QE swarm task: ${task.id} (agents: ${task.agents.join(', ')})`);

      // 1. Propose task allocation via consensus
      const consensusResult = await this.proposeTaskAllocation(task, task.agents);

      if (!consensusResult.accepted) {
        this.logger.warn(`Task allocation rejected: ${consensusResult.reason}`);
        return {
          taskId: task.id,
          agentResults: [],
          completedAgents: 0,
          totalAgents: task.agents.length,
          success: false,
          aggregatedOutput: { error: consensusResult.reason },
        };
      }

      // 2. Broadcast task to allocated workers
      await this.broadcastTask(task);

      // 3. Collect results from workers
      const results = await this.collectResults(task);

      // 4. Aggregate results
      const success = results.filter((r) => r.success).length >= Math.ceil(task.agents.length / 2);

      const swarmResult: QESwarmResult = {
        taskId: task.id,
        agentResults: results,
        completedAgents: results.length,
        totalAgents: task.agents.length,
        success,
        aggregatedOutput: this.aggregateResults(results),
      };

      this.logger.info(`QE swarm task complete: ${task.id} (success: ${success})`);
      return swarmResult;
    } catch (error) {
      this.logger.error(`QE swarm task failed: ${task.id}`, error);
      throw new QEHiveError('Swarm coordination failed', error as Error);
    }
  }

  /**
   * Execute operation with Byzantine fault tolerance
   */
  async executeWithBFT<T>(
    operation: () => Promise<T>,
    replicaCount: number = 3
  ): Promise<T> {
    this.ensureInitialized();

    this.logger.debug(`Executing operation with BFT (replicas: ${replicaCount})`);

    const results: T[] = [];
    const errors: Error[] = [];

    // Execute operation on multiple replicas
    const promises = Array(replicaCount).fill(null).map(async (_, i) => {
      try {
        const result = await operation();
        return { success: true, result, index: i };
      } catch (error) {
        return { success: false, error: error as Error, index: i };
      }
    });

    const outcomes = await Promise.all(promises);

    for (const outcome of outcomes) {
      if (outcome.success) {
        results.push(outcome.result as T);
      } else {
        errors.push(outcome.error as Error);
      }
    }

    // BFT requires 2f+1 agreeing results (f = max faults tolerated)
    // For 3 replicas: f=1, need 2 agreeing
    // For 5 replicas: f=2, need 3 agreeing
    const maxFaults = Math.floor((replicaCount - 1) / 3);
    const requiredAgreement = 2 * maxFaults + 1;

    if (results.length < requiredAgreement) {
      this.logger.error(`BFT consensus failed: ${results.length}/${replicaCount} replicas succeeded`);
      throw new QEHiveError(
        `BFT consensus failed: only ${results.length}/${replicaCount} replicas succeeded`,
        errors[0]
      );
    }

    // Return first successful result (in production, would compare for consensus)
    this.logger.debug(`BFT consensus achieved: ${results.length}/${replicaCount} replicas agreed`);
    return results[0];
  }

  /**
   * Propose task allocation via consensus
   */
  async proposeTaskAllocation(
    task: QESwarmTask,
    requiredAgents: string[]
  ): Promise<ConsensusResult> {
    this.ensureInitialized();

    try {
      this.logger.debug(`Proposing task allocation: ${task.id}`);

      const result = await this.hiveMind.consensus({
        action: 'propose',
        type: 'qe-task-allocation',
        value: {
          taskId: task.id,
          taskType: task.type,
          requiredAgents,
          priority: task.priority,
          proposedBy: this.queenId,
          timestamp: Date.now(),
        },
      });

      return {
        accepted: result.accepted,
        reason: result.reason,
        votesFor: result.votesFor,
        votesAgainst: result.votesAgainst,
        totalVoters: result.totalVoters,
      };
    } catch (error) {
      this.logger.error('Task allocation proposal failed', error);
      throw new QEHiveError('Consensus proposal failed', error as Error);
    }
  }

  /**
   * Broadcast result to hive
   */
  async broadcastResult(taskId: string, result: QESwarmResult): Promise<void> {
    this.ensureInitialized();

    try {
      this.logger.debug(`Broadcasting result for task: ${taskId}`);

      await this.hiveMind.broadcast({
        message: JSON.stringify({
          type: 'qe-result',
          taskId,
          result: {
            success: result.success,
            completedAgents: result.completedAgents,
            totalAgents: result.totalAgents,
            aggregatedOutput: result.aggregatedOutput,
          },
        }),
        priority: result.success ? 'normal' : 'high',
        fromId: this.queenId,
      });

      this.logger.debug(`Result broadcast complete for task: ${taskId}`);
    } catch (error) {
      this.logger.error(`Failed to broadcast result: ${taskId}`, error);
      throw new QEHiveError('Result broadcast failed', error as Error);
    }
  }

  /**
   * Store QE state in hive memory
   */
  async storeQEState(key: string, value: unknown): Promise<void> {
    this.ensureInitialized();

    try {
      const qeKey = `qe:${key}`;
      this.logger.debug(`Storing QE state: ${qeKey}`);

      await this.hiveMind.memory({
        action: 'set',
        key: qeKey,
        value: JSON.stringify(value),
      });
    } catch (error) {
      this.logger.error(`Failed to store QE state: ${key}`, error);
      throw new QEHiveError('Failed to store state', error as Error);
    }
  }

  /**
   * Retrieve QE state from hive memory
   */
  async getQEState<T>(key: string): Promise<T | null> {
    this.ensureInitialized();

    try {
      const qeKey = `qe:${key}`;
      const result = await this.hiveMind.memory({
        action: 'get',
        key: qeKey,
      });

      if (!result.value) return null;

      return JSON.parse(result.value) as T;
    } catch (error) {
      this.logger.error(`Failed to get QE state: ${key}`, error);
      return null;
    }
  }

  /**
   * Leave the hive (cleanup)
   */
  async leave(): Promise<void> {
    if (!this.initialized) return;

    try {
      this.logger.info('QE Queen leaving hive...');

      // Remove all spawned workers
      for (const [workerId] of this.spawnedWorkers) {
        try {
          await this.hiveMind.leave(workerId);
          this.logger.debug(`Worker removed: ${workerId}`);
        } catch {
          // Best effort cleanup
        }
      }
      this.spawnedWorkers.clear();

      // Remove queen
      await this.hiveMind.leave(this.queenId);
      this.initialized = false;

      this.logger.info('QE Queen left hive successfully');
    } catch (error) {
      this.logger.error('Error leaving hive', error);
      throw new QEHiveError('Failed to leave hive', error as Error);
    }
  }

  /**
   * Broadcast task to allocated workers
   */
  private async broadcastTask(task: QESwarmTask): Promise<void> {
    await this.hiveMind.broadcast({
      message: JSON.stringify({
        type: 'qe-task',
        taskId: task.id,
        taskType: task.type,
        payload: task.payload,
        timeout: task.timeout,
        assignedAgents: task.agents,
      }),
      priority: task.priority === 'critical' ? 'critical' : 'normal',
      fromId: this.queenId,
    });
  }

  /**
   * Collect results from workers
   */
  private async collectResults(task: QESwarmTask): Promise<AgentTaskResult[]> {
    const results: AgentTaskResult[] = [];
    const timeout = task.timeout || 30000;
    const startTime = Date.now();

    // Poll for results
    while (Date.now() - startTime < timeout) {
      const resultData = await this.getQEState<AgentTaskResult[]>(`task-results:${task.id}`);

      if (resultData && resultData.length >= task.agents.length) {
        return resultData;
      }

      // Wait before polling again
      await this.sleep(500);
    }

    // Return partial results on timeout
    this.logger.warn(`Task ${task.id} timed out, returning partial results`);
    const partialResults = await this.getQEState<AgentTaskResult[]>(`task-results:${task.id}`);
    return partialResults || [];
  }

  /**
   * Aggregate results from multiple agents
   */
  private aggregateResults(results: AgentTaskResult[]): Record<string, unknown> {
    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    // Merge outputs
    const mergedOutput: Record<string, unknown> = {};
    for (const result of results) {
      if (result.success && result.output) {
        Object.assign(mergedOutput, result.output);
      }
    }

    return {
      summary: {
        total: results.length,
        successful: successCount,
        failed: failureCount,
        successRate: results.length > 0 ? successCount / results.length : 0,
      },
      errors: results.filter((r) => !r.success).map((r) => ({
        agentId: r.agentId,
        error: r.error,
      })),
      mergedOutput,
    };
  }

  /**
   * Get capabilities for an agent type
   */
  private getCapabilitiesForAgent(agentType: string, context: string): string[] {
    const baseCapabilities = [`context:${context}`, agentType];

    // Add context-specific capabilities
    if (context.includes('test-generation')) {
      baseCapabilities.push(...QE_CAPABILITIES.testGeneration);
    } else if (context.includes('test-execution')) {
      baseCapabilities.push(...QE_CAPABILITIES.testExecution);
    } else if (context.includes('coverage')) {
      baseCapabilities.push(...QE_CAPABILITIES.coverageAnalysis);
    } else if (context.includes('quality')) {
      baseCapabilities.push(...QE_CAPABILITIES.qualityAssessment);
    } else if (context.includes('security')) {
      baseCapabilities.push(...QE_CAPABILITIES.securityCompliance);
    }

    return baseCapabilities;
  }

  /**
   * Ensure bridge is initialized
   */
  private ensureInitialized(): void {
    if (!this.initialized) {
      throw new QEHiveError('QEHiveBridge not initialized. Call registerQueen() first.');
    }
  }

  /**
   * Sleep helper
   */
  private sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}

/**
 * QE Hive Error class
 */
export class QEHiveError extends Error {
  public readonly cause?: Error;

  constructor(message: string, cause?: Error) {
    super(message);
    this.name = 'QEHiveError';
    this.cause = cause;
  }
}

/**
 * QE Memory Bridge
 *
 * Anti-corruption layer for V3 memory system integration.
 * Handles storage and retrieval of test patterns, coverage data,
 * and learning trajectories via HNSW-indexed memory.
 *
 * Performance: 150x-12,500x faster search via HNSW indexing
 *
 * Based on:
 * - ADR-030: Agentic-QE Plugin Integration
 * - ADR-006: Unified Memory Service
 *
 * @module v3/plugins/agentic-qe/bridges/QEMemoryBridge
 */

import type {
  IQEMemoryBridge,
  TestPattern,
  PatternFilters,
  CoverageGap,
  LearningTrajectory,
  QEMemoryStats,
  QELogger,
} from '../interfaces.js';

// V3 Memory types (would be imported from @claude-flow/memory in production)
interface IMemoryService {
